import{G as e,K as t,n,ot as r}from"./chunks/framework.C8_jer4d.js";var i=JSON.parse(`{"title":"Lab 3 — Validate Endpoints Before Migration","description":"","frontmatter":{"title":"Lab 3 — Validate Endpoints Before Migration","prev":{"text":"Lab 2: The Challenge"},"next":{"text":"Lab 3: The Challenge"}},"headers":[],"relativePath":"baw-lab/validate-endpoints/index.md","filePath":"baw-lab/validate-endpoints/index.md"}`),a={name:`baw-lab/validate-endpoints/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="lab-3-—-validate-endpoints-before-migration" tabindex="-1">Lab 3 — Validate Endpoints Before Migration <a class="header-anchor" href="#lab-3-—-validate-endpoints-before-migration" aria-label="Permalink to “Lab 3 — Validate Endpoints Before Migration”">​</a></h1><p>In this lab you will ask IBM Bob to check a process application before you move it to a new server. Bob uses the <code>baw-endpoint-validation</code> skill to compare the endpoints of the source and target environments and to scan the application&#39;s TWX export for hardcoded references to the old server. You finish with a readiness verdict and guidance on where to fix each blocker. The skill only reports and explains — it changes nothing in your TWX or on any server.</p><h2 id="🎯-what-you-will-learn" tabindex="-1">🎯 What you will learn <a class="header-anchor" href="#🎯-what-you-will-learn" aria-label="Permalink to “🎯 What you will learn”">​</a></h2><ul><li>How Bob collects the source and target endpoints, and how your prompt controls whether Bob asks questions or uses files it finds in the workspace</li><li>How to verify Bob&#39;s endpoint mappings against your environment specifications before approving changes</li><li>How Bob scans the TWX for hardcoded references to the source servers, without a connection to a BAW server</li><li>How findings are classified as Critical, Warning, or Info, including harmless BAW-internal <code>localhost</code> references that need no change</li><li>How to use the report&#39;s <em>Where to fix</em> guidance to resolve each blocker in Workflow Designer, the Process Admin Console, or on the server, and which fixes need a new snapshot</li></ul>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};